import * as T from 'three';
let rough,normal;
function microtextures(){if(rough)return;const n=128,r=new Uint8Array(n*n*4),b=new Uint8Array(n*n*4);let seed=200;for(let i=0;i<n*n;i++){seed=(1664525*seed+1013904223)>>>0;const v=(seed>>>24)/255;r.set([0,190+Math.round(v*36),0,255],i*4);b.set([127+Math.round(v*2),127+Math.round(((i%n)%5)/4*2),255,255],i*4);}rough=new T.DataTexture(r,n,n);normal=new T.DataTexture(b,n,n);for(const t of[rough,normal]){t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(6,6);t.needsUpdate=true;t.userData.quality100Shared=true;}}
export function substationFinish200(model,parts){if(model.userData.finish200)return;microtextures();const materials=new Map();model.traverse(o=>{if(!o.isMesh)return;const finish=m=>{if(!m?.isMeshStandardMaterial)return m;if(materials.has(m))return materials.get(m);const name=m.name.toLowerCase();if(!/cobre|acero|chapa|aisl|resina|bobina|esmalte|ceram|porcel|zapata|hormig|concreto/.test(name))return m;const n=m.clone();if(/cobre|zapata/.test(name)){n.metalness=.82;n.roughness=.32;n.envMapIntensity=.85;}else if(/aisl|resina|bobina|esmalte|ceram|porcel/.test(name)){n.metalness=Math.min(n.metalness,.12);n.roughness=/negro/.test(name)?.74:.39;}else if(/hormig|concreto/.test(name)){n.roughness=.94;n.envMapIntensity=.25;}else{n.roughness=Math.min(Math.max(n.roughness,.32),.58);n.envMapIntensity=.75;}if(!n.roughnessMap)n.roughnessMap=rough;if(!n.normalMap){n.normalMap=normal;n.normalScale.set(.08,.08);}n.userData={...n.userData,finish200:true};materials.set(m,n);return n;};o.material=Array.isArray(o.material)?o.material.map(finish):finish(o.material);});
 const g=new T.Group();g.name='Terminaciones y cableado visible200';g.userData.illustrative200=true;parts.get('transformer').add(g);
 const steel=new T.MeshStandardMaterial({name:'Acero satinado terminaciones200',color:'#a6b0b2',metalness:.82,roughness:.34,roughnessMap:rough}),copper=new T.MeshStandardMaterial({name:'Cobre estañado zapata200',color:'#b7a18a',metalness:.86,roughness:.33,roughnessMap:rough}),insulator=new T.MeshStandardMaterial({name:'Aislador soporte terminal200',color:'#835b39',roughness:.36}),rubber=new T.MeshStandardMaterial({name:'Cubierta flexible de cable200',color:'#20262a',roughness:.80}),paint=new T.MeshStandardMaterial({name:'Caja de conexiones pintada200',color:'#647575',metalness:.12,roughness:.5});
 const box=(name,x,y,z,w,h,d,mat)=>{const o=new T.Mesh(new T.BoxGeometry(w,h,d),mat);o.name=name;o.position.set(x,y,z);o.userData.connection200=true;g.add(o);return o;};
 const cylinder=(name,a,b,r,mat,sides=20)=>{const A=new T.Vector3(...a),B=new T.Vector3(...b),o=new T.Mesh(new T.CylinderGeometry(r,r,A.distanceTo(B),sides),mat);o.name=name;o.position.copy(A).add(B).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),B.sub(A).normalize());g.add(o);return o;};
 box('Placa aislada de apoyo de salidas200',-.35,1.305,1.21,.028,.82,.53,paint);
 for(const y of[1.03,1.58])for(const z of[1.05,1.21,1.37]){cylinder('Manguito de terminación200',[-.69,y,z],[-.55,y,z],.028,rubber);cylinder('Zapata conectada al extremo existente200',[-.57,y,z],[-.42,y,z],.020,copper);cylinder('Separador aislante200',[-.43,y,z],[-.35,y,z],.035,insulator);box('Lengüeta estañada200',-.465,y,z,.13,.052,.062,copper);cylinder('Perno y tuerca de conexión200',[-.47,y+.021,z],[-.47,y+.057,z],.014,steel,6);}
 box('Caja de bornes ventilación200',-3.03,.42,1.28,.15,.15,.12,paint);for(const y of[.37,.47])for(const z of[1.235,1.325])cylinder('Tornillo tapa bornes200',[-3.113,y,z],[-3.12,y,z],.006,steel,12);
 for(const x of[-2.75,-.95]){box('Caja terminal del motor200',x+.09,.49,1.26,.09,.09,.075,paint);cylinder('Prensaestopa del motor200',[x+.14,.49,1.26],[x+.18,.49,1.26],.020,steel);const points=[[x+.18,.49,1.26],[x+.21,.39,1.32],[x,.34,1.34],[-2.90,.34,1.34],[-2.96,.41,1.28]].map(p=>new T.Vector3(...p)),curve=new T.CatmullRomCurve3(points);const cable=new T.Mesh(new T.TubeGeometry(curve,42,.010,10,false),rubber);cable.name='Cable continuo sujeto a la base200';g.add(cable);for(const t of[.20,.5,.78]){const p=curve.getPoint(t);box('Abrazadera de guiado200',p.x,p.y-.005,p.z,.055,.027,.036,steel);}}
 model.userData.finish200={terminations:6,motorLeads:2,scope:'Terminaciones visuales de las salidas y motores existentes; sin asignar datos nominales ni una topología eléctrica nueva.'};
}
